<script lang="ts">import { untrack } from "svelte"; import { useRuntime } from "../../../app/runtime.svelte"; import SystemFrame from "../../../components/SystemFrame.svelte"; import RouterLink from "../../../components/RouterLink.svelte"; import { createWorkspaceStorageBindingsController } from "./workspace-storage-bindings-controller.svelte"; const runtime = useRuntime(); const controller = untrack(() => createWorkspaceStorageBindingsController({ activity: runtime.activity, onAuthenticationLost: runtime.requireLogin, onSystemAccessChange: runtime.access.setSystemAccess })); $effect(() => { void controller.load() }); $effect(() => controller.start())</script><SystemFrame active="workspace-storage-bindings" title="Workspace storage bindings"><section class="system-page"><div class="system-page-heading mb-5"><div><p class="eyebrow">System</p><h2 class="title is-3">Workspace storage bindings</h2><p class="subtitle is-6">Bind global storage providers to workspaces.</p></div><RouterLink class="button is-primary" href="/app/system/workspace-storage-bindings/new">Add binding</RouterLink></div><div class="system-grant-list">{#each controller.state.bindings as b (`${b.workspace}/${b.provider}`)}<RouterLink class={`system-grant-row${b.enabled ? "" : " system-grant-disabled"}`} href={`/app/system/workspace-storage-bindings/${encodeURIComponent(b.workspace)}/${encodeURIComponent(b.provider)}`}><div><strong>{b.workspace} / {b.provider}</strong><small>priority {b.priority} / revision {b.revision}</small></div><span>{b.enabled ? "Enabled" : "Disabled"}</span></RouterLink>{:else}<p class="dashboard-empty">No workspace storage bindings are configured.</p>{/each}</div></section></SystemFrame>
